entries[213163] = { ["name"] = "Cryptographic Glyph", ["text"] = "Quest Item\nUnique (8)\n\"The rune carved into the stone seems to shimmer and change its shape as you lay eyes upon it.\"" }
entries[213164] = { ["name"] = "Gnomish Gravity Launcher", ["text"] = "Consumable\nUse: Deploy a Gnomish Gravity Launcher, granting anyone who steps on it the ability to soar through the air.\n\nJump to activate. Land on enemies to inflict damage!\nSell Price:" }
entries[213171] = { ["name"] = "Pristine Horn", ["text"] = "Quest Item\nRequires level 70 to 73 ( 73)\n\"The rings on this horn tell the age of the shalehorn. It is smooth, durable, and will make a beautiful, high-quality instrument.\"" }
entries[213172] = { ["name"] = "A Red Missive", ["text"] = "Binds when picked up\n\"A letter soaked in blood.\"\n<Right Click to Read>" }
entries[213173] = { ["name"] = "Thread of Power", ["text"] = "Quest Item\nRequires level 10 to 80 ( 80)" }
entries[213175] = { ["name"] = "Dusty Djaradin Tome", ["text"] = "Binds when picked up\n\"A small archive of djaradin history.\"\n<Right Click to Open>" }
entries[213176] = { ["name"] = "Preserved Isles Tome", ["text"] = "Binds when picked up\n\"A large archive of history on the centaur and the niffen.\"\n<Right Click to Open>" }
entries[213177] = { ["name"] = "Immaculate Tome", ["text"] = "Binds when picked up\n\"An enormous archive of Dragon Isles history!\"\n<Right Click to Open>" }
entries[213178] = { ["name"] = "Undercrawler Venom", ["text"] = "Quest Item\n\"Paralytic venom. Undercrawlers prefer to keep their prey alive.\"" }
entries[213179] = { ["name"] = "Cracked Draconic Tooth", ["text"] = "\"The damage indicates this tooth was knocked out by a blow. Its owner must have had a disagreement with something.\"\nSell Price:" }
entries[213180] = { ["name"] = "Crumpled Map", ["text"] = "\"Someone began plotting a battlefield on this parchment... only to scribble the whole thing out and throw it away\"\nSell Price:" }
entries[213181] = { ["name"] = "A Tiny Dragon Goblet", ["text"] = "Binds when picked up\nUnique\nUse: When summoned, Pepe will sometimes be dressed like a dragon." }
entries[213182] = { ["name"] = "Worry Stone", ["text"] = "\"A clawed hand has rubbed quite a deep indent in this stone.\"\nSell Price:" }
entries[213183] = { ["name"] = "Makeshift Beaded Bracelet", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"The beads consist of scraps of wire and scavenged stones. The string has been repaired many times.\"\nSell Price:" }
entries[213184] = { ["name"] = "Rock with Chewed Gum", ["text"] = "\"Students never change. At least the gum is interesting, made from the sap of a local tree.\"\nSell Price:" }
entries[213185] = { ["name"] = "Dusty Centaur Tome", ["text"] = "Binds when picked up\n\"A small archive of centaur history.\"\n<Right Click to Open>" }
entries[213186] = { ["name"] = "Dusty Niffen Tome", ["text"] = "Binds when picked up\n\"A small archive of niffen history.\"\n<Right Click to Open>" }
entries[213187] = { ["name"] = "Dusty Drakonid Tome", ["text"] = "Binds when picked up\n\"A small archive of drakonid history.\"\n<Right Click to Open>" }
entries[213188] = { ["name"] = "Dusty Dracthyr Tome", ["text"] = "Binds when picked up\n\"A small archive of dracthyr history.\"\n<Right Click to Open>" }
entries[213189] = { ["name"] = "Preserved Dragonkin Tome", ["text"] = "Binds when picked up\n\"A large archive of history on the drakonids and the dracthyr.\"\n<Right Click to Open>" }
entries[213190] = { ["name"] = "Preserved Djaradin Tome", ["text"] = "Binds when picked up\n\"A large archive of history on the djaradin.\"\n<Right Click to Open>" }
entries[213191] = { ["name"] = "Arathi Tinderbox", ["text"] = "Quest Item\n\"Keep the Sacred Flame with you, everywhere you go.\"" }
entries[213192] = { ["name"] = "Scratched-Out List of Names", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"Someone made sure that each name was rendered illegible before discarding the list.\"\nSell Price:" }
entries[213193] = { ["name"] = "Arathi Army Medallion", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"Muck stains its polished surface\"" }
entries[213194] = { ["name"] = "Petrified Rations", ["text"] = "\"This clump of hardened foodstuffs could offer insight into what was eaten on this island.\"\nSell Price:" }
entries[213195] = { ["name"] = "Charred Doodle", ["text"] = "\"Most of this paper has been destroyed, but the parts you can make out depict horns and angry eyebrows.\"\nSell Price:" }
entries[213196] = { ["name"] = "Pressed Flower", ["text"] = "\"This bloom was dried and pressed, preserved between the pages of a now-lost book.\"\nSell Price:" }
entries[213197] = { ["name"] = "Null Lotus", ["text"] = "Crafting Reagent\n\"A rare herb that emanates a feeling of nothingness. Sometimes gathered by players with the Herbalism skill. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[213200] = { ["name"] = "Book of Horoscopes", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"It's a marvel a book this flimsy has survived. The scribbles within suggest that someone took this nonsense very seriously.\"\nSell Price:" }
entries[213201] = { ["name"] = "Discarded Waterfowl Bones", ["text"] = "\"The dragonkin here were fond of ducks, but these bones suggest they were at times used for food.\"\nSell Price:" }
entries[213202] = { ["name"] = "A Tiny Explorer's Hat", ["text"] = "Binds when picked up\nUnique\nUse: When summoned, Pepe will sometimes be dressed like an explorer." }
entries[213203] = { ["name"] = "Velvet Nightcap", ["text"] = "\"This fine hood must have belonged to someone important. It has two holes cut out for horns.\"\nSell Price:" }
entries[213204] = { ["name"] = "Ruby-Studded Locket", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"Inside, there is a sketch of a red drakonid guard with a handsome grin.\"\nSell Price:" }
entries[213205] = { ["name"] = "Mad Scribblings", ["text"] = "\"These star charts go far afield of reality. Studying the stars isn't for the faint of heart.\"\nSell Price:" }
entries[213206] = { ["name"] = "Charred Letter", ["text"] = "\"The legible bits suggest this was once an angry rebuttal from a fellow scholar.\"\nSell Price:" }
entries[213207] = { ["name"] = "A Tiny Ear Warmer", ["text"] = "Binds when picked up\nUnique\nUse: When summoned, Pepe will sometimes be dressed like as a tuskarr." }
entries[213208] = { ["name"] = "Pot of Pickled Ancheevies", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"Someone must have been saving these for a special occasion that never arose.\"\nSell Price:" }
