entries[213357] = { ["name"] = "Crystal Scrying Bowl", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"Peering into the bowl, it feels like you can almost make out an image. Or that's your reflection.\"\nSell Price:" }
entries[213358] = { ["name"] = "Indelicately Excavated Skull", ["text"] = "\"There may have been great wisdom to be gleaned from this rare find, but whoever found it first plunged a pickaxe straight into it!\"\nSell Price:" }
entries[213359] = { ["name"] = "Cracked Drakonid Staff", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"Time has rendered this magical focus inert, but the engravings along the shaft tell an even deeper story.\"\nSell Price:" }
entries[213360] = { ["name"] = "Discarded Drakonid Amulet", ["text"] = "\"The gem this amulet once held has been pried free, reducing its value to nearly worthless.\"\nSell Price:" }
entries[213361] = { ["name"] = "Disquieting Children's Toy", ["text"] = "\"Children have taken an alarming shine to unsettling figurines. Maybe it's better left a mystery.\"\nSell Price:" }
entries[213362] = { ["name"] = "Ancient Drakonid Candy", ["text"] = "Use: Eat me.\n\"It may have retained its form, but surely this rock-hard drakonid treat is past its expiration date.\"\nSell Price:" }
entries[213363] = { ["name"] = "Molted Eye Skin", ["text"] = "\"When reptiles shed their scales, many species shed the skin on their eyes as well. During this time, the creatures are often blind and defenseless.\"\nSell Price:" }
entries[213364] = { ["name"] = "Empty Vial of Perfume", ["text"] = "\"A lovely aroma still lingers on the rim.\"\nSell Price:" }
entries[213365] = { ["name"] = "Carved Cave Crystal", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"Intricate shapes have been carved into this crystal, causing the light to shine in unique patterns.\"\nSell Price:" }
entries[213366] = { ["name"] = "Strip of Niffen Headwear", ["text"] = "\"Comparing the material and design of this niffen hat to ones commonly used today, one can extrapolate the evolution of niffen fashion.\"\nSell Price:" }
entries[213367] = { ["name"] = "Discarded Claw Prototype", ["text"] = "\"This appears to be a rudimentary attempt at upgrading niffen digging capabilities. The project seems to have been scrapped due to lack of necessity.\"\nSell Price:" }
entries[213368] = { ["name"] = "Scratch-and-Sniff Stone", ["text"] = "\"Scratching this stone goes against all archaeological principles. Sure is tempting though.\"\nSell Price:" }
entries[213374] = { ["name"] = "Niffen Noseplug", ["text"] = "\"Niffen noses are so sensitive, sometimes they just need a way to shut out the day and get some sleep.\"\nSell Price:" }
entries[213375] = { ["name"] = "Satchel of Buried Valuables", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"On the rare occasion that a niffen forgets where they buried their shinies, these lost pouches act as effective time capsules.\"\nSell Price:" }
entries[213377] = { ["name"] = "Mutliated Storybook", ["text"] = "\"Massive niffen claws don't mix well with delicate books. At least they tried.\"\nSell Price:" }
entries[213380] = { ["name"] = "Unidentifiable Equine Fossil", ["text"] = "\"Does this go in the centaur pile or the horse pile?\"\nSell Price:" }
entries[213382] = { ["name"] = "Partial Centaur Hunting Map", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"One can learn a lot about the local centaur by the way they hunt. This map fragment demonstrates the surprising coordination of ancient hunting parties.\"\nSell Price:" }
entries[213384] = { ["name"] = "Horsehair Doll", ["text"] = "\"Passed down from generation to generation, each parent adding to the stitching.\"\nSell Price:" }
entries[213385] = { ["name"] = "Stiff Brush", ["text"] = "\"There is no greater sign of intimacy and trust between centaur than mutual grooming.\"\nSell Price:" }
entries[213386] = { ["name"] = "Unearthed Stone Arrowhead", ["text"] = "\"The shape and size of the arrowhead reveals much of how centaur hunting has adapted over the years.\"\nSell Price:" }
entries[213387] = { ["name"] = "Primitive Centaur Carving", ["text"] = "\"A tradition dating back as far as records go, many centaur across the plains share a love of whittling.\"\nSell Price:" }
entries[213388] = { ["name"] = "Faded Centaur Painting", ["text"] = "\"Being a nomad means you can't take your cave drawings with you. Inventive centaur of the past solved this problem with their own painting skins.\"\nSell Price:" }
entries[213389] = { ["name"] = "Ancient Centaur Diary", ["text"] = "Binds when picked up\nUse: Break down this relic into a small amount of Mysterious Fragments.\n\"Seemingly written from the perspective of a child, this diary does much to showcase what life was like for early centaur.\"\nSell Price:" }
entries[213392] = { ["name"] = "Scent Grenade", ["text"] = "Quest Item\nUse: Throw a strong-smelling grenade to stun a Feral Battleshell and alert a Rak-Ush niffen of their location.\n\"A nerubian-made grenade, full of nice, calming smoke. If you're a beetle, that is.\"" }
entries[213393] = { ["name"] = "Guise of the Golden Masquerade", ["text"] = "Cosmetic\nBinds to Warband\nHead Cosmetic\n\"The dazzling gold masks the wearers identity and wows onlookers.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[213394] = { ["name"] = "Ebony Crown of the Red Rose", ["text"] = "Cosmetic\nBinds to Warband\nHead Cosmetic\n\"Every night has its dawn.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[213395] = { ["name"] = "Gloves of the Midnight Soiree", ["text"] = "Cosmetic\nBinds to Warband\nHands Cosmetic\n\"Fitting attire for a midnight rendezvous.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
