entries[213595] = { ["name"] = "Feathered Windsurfer String", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Check the current windspeed and elevation before mounting. Avoid trees and other tall objects. Damaged kites are ineligible for return or refund.\" - Windsurfer's Instruction Manual\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213596] = { ["name"] = "Reins of the Daystorm Windsteed", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"It is said that when lightning strikes the sun, a gleaming beast in red armor would emerge from the heavens. The Daystorm Windsteed has never heard of these legends and has been here the entire time.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213597] = { ["name"] = "Reins of the Forest Windsteed", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The fur of this Windsteed is not only colored to match its woodland home, but also usually contains bits of bark and leaves.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213598] = { ["name"] = "Reins of the Dashing Windsteed", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Windsteeds are incredibly gentle and easy to train... if you can catch one.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213600] = { ["name"] = "Reins of the Marble Quilen", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Created by a mogu sorcerer who breathed life into their favorite pet rock.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213601] = { ["name"] = "Reins of the Guardian Quilen", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"When Quan the Relentless fell in battle, his loyal hounds waited for his return. Millenia later, they remain patient.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213602] = { ["name"] = "Reins of the Gilded Riding Crane", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"It is said that an emperor once paid a large sum for a golden crane. Upon discovering that the crane was only colored like that of the precious metal, he hid with shame in his bedchambers for a week.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213603] = { ["name"] = "Reins of the Pale Riding Crane", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"I looked, and behold, a pale... crane?\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213604] = { ["name"] = "Reins of the Tropical Riding Crane", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This Jade Forest native uses its coloration as camouflage.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213605] = { ["name"] = "Reins of the Rose Riding Crane", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This brightly-colored bird is often confused with a flamingo or marabou.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213606] = { ["name"] = "Reins of the Silver Riding Crane", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This tall bird is one of the most graceful and elegant cranes, slightly moreso than the Bronze Crane but less than the Golden Crane.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213607] = { ["name"] = "Reins of the Luxurious Riding Crane", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A majestic bird, but a rather picky eater.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213608] = { ["name"] = "Reins of the Snowy Riding Goat", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The Kun-Lai Summit mountain goats are known for climbing even the highest peaks in search of kafa beans and salt licks.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213609] = { ["name"] = "Reins of the Little Red Riding Goat", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"What this goat lacks in size, it makes up for in stubbornness.\"\nWorld Event:\nMists of Pandaria: Remix" }
entries[213610] = { ["name"] = "Crystalline Powder", ["text"] = "Crafting Reagent\n\"A fine, magical powder made from the crystallized fragments of a crystalline herb or ore. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[213611] = { ["name"] = "Writhing Sample", ["text"] = "Crafting Reagent\n\"A small, writhing sample of biomass found within an Altered herb or Weeping ore. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[213612] = { ["name"] = "Viridescent Spores", ["text"] = "Crafting Reagent\n\"A cluster of spores, teeming with life energy. Acquired by players with the Herbalism skill. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[213613] = { ["name"] = "Leyline Residue", ["text"] = "Crafting Reagent\n\"A substance containing light hints of remnant arcane energy. Acquired by players with the Herbalism skill. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[213621] = { ["name"] = "Reins of the Jade Pterrordax", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This favored mount of the Zandalari is a great singer, or so it thinks.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213622] = { ["name"] = "Reins of the Night Pterrorwing", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Scholars interpret this creature's awful screeching as \"fear me, I am the night!\"\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213623] = { ["name"] = "Reins of the Bloody Skyscreamer", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This dinosaur still harbors the rage of its ancestors from the Zandalari Invasion.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213624] = { ["name"] = "Cobalt Juggernaut", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"What started as a rideable mining and logging machine devolved quickly into chaos when engineers asked themselves if they could make it any cooler.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213625] = { ["name"] = "Fel Iron Juggernaut", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"This war machine was stolen from a timeline in which Garrosh Hellscream joined the Burning Legion. Suffice it to say, there is not much left of that timeline.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213626] = { ["name"] = "Reins of the Purple Shado-Pan Riding Tiger", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"When waking a tiger, use a long stick. Better yet, tell your friend to wake the tiger instead.\" -Pandaren Proverb\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213627] = { ["name"] = "Reins of the Palehide Mushan Beast", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The Palehide Mushan is the tastiest of Mushan beasts, but it hates being reminded of that fact.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213628] = { ["name"] = "Reins of the Riverwalker Mushan", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The Mushan is a voracious beast. Though it can be tamed, it will demand a second, third, and even fourth breakfast every day.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[213629] = { ["name"] = "Debugger Hat", ["text"] = "Quest Item\nUse: Deals 20 Nature damage to the current enemy target, jumping to nearby targets with... unpredictable results. May also jump to non-test creatures. (8 Sec Cooldown)\n\"Jenni's invention should remove bugs near Mmarl. In theory.\"" }
entries[213630] = { ["name"] = "Keg of Black Powder", ["text"] = "Quest Item\n\"Spider repellant.\"" }
entries[213631] = { ["name"] = "Empty Spool of Temporal Threads", ["text"] = "Quest Item\nRequires level 10 to 80 ( 80)\n\"Previously used to hold the fabric of time.\"" }
